def get_relevant(query):
    q = query.lower()
    scored = []
    for w in WRITINGS:
        score = sum(1 for word in q.split() if len(word)>3 and word in w.lower())
        if "pain" in q and "pain" in w.lower(): score+=2
        if "word" in q and "word" in w.lower(): score+=2
        if "family" in q and "family" in w.lower(): score+=3
        scored.append((score + random.random()*0.5, w))
    scored.sort(reverse=True)
    return scored[0][1], scored[1][1]

def chat_fn(msg, hist):
    a,b = get_relevant(msg)
    opener = random.choice(["Here's what I wrote about that —","I lived this —","From my pages:","Listen:"])
    return f"{opener}\n\n{a}\n\n---\n{b[:600]}"

with gr.Blocks(theme=gr.themes.Soft()) as demo:
    gr.Markdown("# DAVID ALEXANDER AI\n### I set myself ablaze for the world to watch me burn\nSelf Therapy. What's on your mind today?")
    gr.ChatInterface(chat_fn, examples=["I feel pain", "I feel isolated", "How do I change my words?", "Life feels like a game"])

