def get_relevant(query):
    q = query.lower()
    # score by overlap + random to avoid same answer
    scored = []
    for w in WRITINGS:
        score = sum(1 for word in q.split() if len(word)>3 and word in w.lower())
        # boost if emotion matches
        if any(k in q for k in ["pain","hurt","broken"]):
            if "pain" in w.lower() or "rock" in w.lower(): score+=2
        if any(k in q for k in ["word","speak","write"]):
            if "word" in w.lower(): score+=3
        scored.append((score + random.random(), w))
    scored.sort(reverse=True)
    return [w for s,w in scored[:2]]

def chat_fn(msg, hist):
    picks = get_relevant(msg)
    # make it dynamic
    intro = random.choice([
        "Look —",
        "Listen to this:",
        "This is where it clicks —",
        "From my own pages —",
        "I wrote this when I was in it:"
    ])
    return f"{intro}\n\n{picks[0][:1200]}\n\n---\n\nAnd this:\n{picks[1][:800]}\n\n🔥 Action: Take one line and speak it out loud today. Word made flesh."

with gr.Blocks(theme=gr.themes.Soft()) as demo:
    gr.Markdown("# DAVID ALEXANDER AI\n### I set myself ablaze for the world to watch me burn\nSelf Therapy. Whats on your mind today?.")
    gr.ChatInterface(chat_fn, examples=["I'm stuck", "Talk about words", "I feel pain", "How do I reprogram?"])

demo.launch(server_name="0.0.0.0", server_port=int(os.environ.get("PORT", 7860)))
